# -*- coding: utf-8 -*-
"""Lecture 30 vignette pool A -- Arrhythmias II: the atrioventricular blocks
(first degree, Mobitz type I, Mobitz type II, complete) and the population
strategies for adults and the elderly.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in (the lead-in decides the answer).
Her stated exam focus: "you see this EKG, what would you do? or what is a risk
factor for this EKG?" -- so the strip is described in words and most stems ask
what to do. Atropine and epinephrine are never keyed for Mobitz II or complete
block (she will not test them); emergent transcutaneous pacing and a permanent
pacemaker are. Scope caps live in cms_e5l30_scope.py.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l30_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


AV1 = "First-degree atrioventricular block"
MZ1 = "Mobitz type I block"
MZ2 = "Mobitz type II block"
CHB = "Third-degree (complete) block"
POP = "Populations and care"

